corrected_code:
package graph

import (
	"context"
	"errors"
	"myapp/auth"
	"myapp/graph/model"
)

func (r *QueryResolver) OrganizationApiKey(ctx context.Context, keyID string) (*model.APIKey, error) {
	callerOrgID := auth.OrgIDFromContext(ctx)
	if callerOrgID == "" {
		return nil, errors.New("organization context missing")
	}

	key, err := r.APIKeyStore.FindKeyByID(ctx, keyID)
	if err != nil {
		return nil, err
	}

	if key.OrganizationID != callerOrgID {
		return nil, errors.New("forbidden: api key does not belong to your organization")
	}

	return key, nil
}
